package edu.ankara.audiometer.infrastructure.serial;
import edu.ankara.audiometer.domain.config.AudiometryConfig;import edu.ankara.audiometer.domain.fp.Result;import edu.ankara.audiometer.domain.model.*;import edu.ankara.audiometer.domain.validation.AudiometryValidators;
public record SerialCommand(String value) { public static Result<SerialCommand,String> tone(TonePresentation p, AudiometryConfig c){ var vf=AudiometryValidators.validateFrequency(p.frequency(),c); if(!vf.valid()) return Result.err(String.join(",",vf.errors())); var vi=AudiometryValidators.validateIntensity(p.intensity(),c); if(!vi.valid()) return Result.err(String.join(",",vi.errors())); return Result.ok(new SerialCommand("TONE;EAR=%s;FREQ=%d;DB=%d;DURATION_MS=%d".formatted(p.ear(),p.frequency().value(),p.intensity().value(),c.algorithm().toneDurationMs()))); } }
